import java.util.*;

public class Main {
    static int[][] vis = new int[110][110];
    static int[][] f = {{0,1},{1,0},{0,-1},{-1,0}};

    static class Node {
        int x, y, step;
        Node(int x, int y, int step) {
            this.x = x;
            this.y = y;
            this.step = step;
        }
    }

    static PriorityQueue<Node> q = new PriorityQueue<>(new Comparator<Node>() {
        public int compare(Node n1, Node n2) {
            return Integer.compare(n1.step, n2.step);
        }
    });

    static int bfs(int l, int u, int xi, int yi) {
        Node e = new Node(l, u, 0);
        q.add(e);
        vis[e.x][e.y] = 1;
        while (!q.isEmpty()) {
            e = q.poll();
            if (e.x == xi && e.y == yi) return e.step;
            for (int i = 0; i < 4; i++) {
                int tx = e.x + f[i][0];
                int ty = e.y + f[i][1];
                int tstep = e.step + 1;
                if (tx < 0 || ty < 0) continue;
                if (vis[tx][ty] != 0) continue;
                vis[tx][ty] = 1;
                q.add(new Node(tx, ty, tstep));
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        int len = s.length();
        int x = 0, y = 0, xx = 0, yy = 0;
        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (c == 'L') y--;
            if (c == 'R') y++;
            if (c == 'U') x--;
            if (c == 'D') x++;
            xx = Math.min(xx, x);
            yy = Math.min(yy, y);
        }
        xx = -xx;
        yy = -yy;
        for (int i = 0; i < 110; i++) {
            for (int j = 0; j < 110; j++) vis[i][j] = 1;
        }
        x = xx;
        y = yy;
        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (c == 'L') y--;
            if (c == 'R') y++;
            if (c == 'U') x--;
            if (c == 'D') x++;
            vis[x][y] = 0;
        }
        int ans = bfs(xx, yy, x, y);
        if (ans == len) System.out.println("OK");
        else System.out.println("BUG");
    }
}
